mapper.select:



        c.title like #{cmsInfo.title}


        and c.cate = #{cmsInfo.cate}


        and u.nickname = #{cmsInfo.createrNickname}


        and create_time > date_format(#{cmsInfo.startTime},'%Y-%m-%d %H:%i:%s') and
        create_time < date_format(#{cmsInfo.endTime},'%Y-%m-%d %H:%i:%s')

    and c.is_deleted = 0

order by c.create_time desc
